            { "Wait for the title screen to finish loading.", new[] { "Wait for the title screen to finish loading.", "Espera a que cargue la pantalla de inicio.", "\u8bf7\u7b49\u5f85\u6807\u9898\u753b\u9762\u52a0\u8f7d\u5b8c\u6210\u3002", "\u0414\u043e\u0436\u0434\u0438\u0442\u0435\u0441\u044c \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u0433\u043b\u0430\u0432\u043d\u043e\u0433\u043e \u043c\u0435\u043d\u044e." } }
        };
        public static string Normalize(string code) { return Array.IndexOf(Codes, code) >= 0 ? code : "en"; }
        public static string FromGameLanguage(string language) {
            switch ((language ?? "").ToUpperInvariant()) {
                case "SPANISH": return "es";
                case "CHINESE": return "zh";
                case "RUSSIAN": return "ru";
                default: return "en";
            }
        }
        public static string Get(string code, string key) {
            string[] values; return key != null && Texts.TryGetValue(key, out values) ? values[Array.IndexOf(Codes, Normalize(code))] : key ?? "";
        }
        public static IEnumerable<string> Keys { get { return Texts.Keys; } }
    }
}
